import Typography from "@mui/material/Typography";
import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";
import Box from "@mui/material/Box";
import IconButton from "@mui/material/IconButton";
import CustomDataGrid from "src/@core/components/data-grid";
import Chip from "@mui/material/Chip";
import { styled } from "@mui/material/styles";
import { Avatar, Button } from "@mui/material";
import { MEDIA_URL } from "src/network/endpoints";
import FileUploadIcon from "@mui/icons-material/FileUpload";
import DeleteOutlineIcon from "@mui/icons-material/DeleteOutline";

const TableOverviewMainTitle = ({
  rows,
  totalCount,
  setCurrentPage,
  currentPage,
  setPageSize,
  pageSize,
  loading,
  toggleEdit,
  toggleDelete,
  onCellClick,
  toggleUploadPdf,
  uploadPdfButtonVisible,
  deletePdfButtonVisible,
}) => {
  const statusColors = {
    inactive: "#FFB400",
    active: "#66bb6a",
  };
  const CustomChip = styled(Chip)(({ label }) => ({
    backgroundColor: statusColors[label] || statusColors.default,
    textTransform: "capitalize",
    color: "#fff",
    width: "100px",
  }));
  return (
    <>
      <CustomDataGrid
        loading={loading}
        rowCount={totalCount}
        rows={rows}
        handleCellClick={onCellClick}
        columns={[
          {
            field: "title_1",
            minWidth: 300,
            flex: 1,
            sortable: false,
            headerName: "Main Title",
            renderCell: ({ row }) => (
              <Typography noWrap variant="body2" title={row.title_1}>
                {row.title_1}
              </Typography>
            ),
          },
          {
            field: "title_2",
            minWidth: 300,
            flex: 1,
            sortable: false,
            headerName: "Overview List Title",
            renderCell: ({ row }) => (
              <Typography noWrap variant="body2" title={row.title_2}>
                {row.title_2}
              </Typography>
            ),
          },
          {
            field: "title_3",
            minWidth: 300,
            flex: 1,
            sortable: false,
            headerName: "Overview Table Title",
            renderCell: ({ row }) => (
              <Typography noWrap variant="body2" title={row.title_3}>
                {row.title_3}
              </Typography>
            ),
          },

          {
            field: "Actions",
            flex: 0.6,
            minWidth: 250,
            sortable: false,
            headerName: "Actions",
            renderCell: ({ row }) => (
              <Box display="flex" alignItems="center" gap="10px">
                <IconButton
                  size="small"
                  color="primary"
                  variant="outlined"
                  onClick={(e) => {
                    e.stopPropagation();
                    toggleEdit(e, "edit", row);
                  }}
                >
                  <EditIcon />
                </IconButton>
                <IconButton
                  size="small"
                  color="secondary"
                  onClick={(e) => {
                    e.stopPropagation();
                    toggleDelete(e, "delete details", row);
                  }}
                >
                  <DeleteIcon />
                </IconButton>
                {uploadPdfButtonVisible && (
                  <Button
                    size="small"
                    variant="contained"
                    endIcon={<FileUploadIcon />}
                    onClick={(e) => {
                      e.stopPropagation();
                      toggleUploadPdf();
                    }}
                  >
                    Add PDF
                  </Button>
                )}
                {deletePdfButtonVisible && (
                  <Button
                    size="small"
                    variant="contained"
                    endIcon={<DeleteOutlineIcon />}
                    onClick={(e) => {
                      e.stopPropagation();
                      toggleDelete(e, "delete pdf", row);
                    }}
                  >
                    Delete PDF
                  </Button>
                )}
              </Box>
            ),
          },
        ]}
        currentPage={currentPage}
        pageSize={pageSize}
        setCurrentPage={setCurrentPage}
        setPageSize={setPageSize}
      />
    </>
  );
};

export default TableOverviewMainTitle;
